IF EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.poi_translations') AND name COLLATE Latin1_General_100_BIN2=N'PoiId') EXEC sys.sp_rename N'dbo.poi_translations.PoiId',N'poi_id',N'COLUMN';
